source='''from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            queue = deque([(r, c)])
            while queue:
                cr, cc = queue.popleft()
                for nr, nc in ((cr - 1, cc), (cr + 1, cc), (cr, cc - 1), (cr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr, nc))
                        cells.add((nr, nc))
                        queue.append((nr, nc))
            min_r = min(rr for rr, _ in cells)
            min_c = min(cc for _, cc in cells)
            shape = frozenset((rr - min_r, cc - min_c) for rr, cc in cells)
            components.append((color, cells, shape))

    out = [row[:] for row in grid]
    for color, cells, shape in components:
        if color != 1:
            continue
        matches = [other_color for other_color, _, other_shape in components
                   if other_color != 1 and other_shape == shape]
        if matches:
            replacement = matches[0]
            for r, c in cells:
                out[r][c] = replacement
    return out
